import numpy as np
def softmax(z):
    e = np.exp(z - np.max(z))   # subtract max for numerical stability
    return e / e.sum()
# attention turns raw scores into weights that sum to 1
print(np.round(softmax(np.array([1.0, 2.0, 3.0])), 3).tolist())

