import numpy as np
def softmax(z):
    e = np.exp(z - np.max(z))   # resta el máximo por estabilidad numérica
    return e / e.sum()
# la atención convierte puntuaciones en pesos que suman 1
print(np.round(softmax(np.array([1.0, 2.0, 3.0])), 3).tolist())
